-- Generated by scripts/build-explorer-sql.py from explorer/sql: edit those files, not this one.
WITH
-- Units: one row per data center from the chosen source ({{SOURCE}}), with its H3 res-8
-- cells. Shared by every theme: scripts/build-explorer-sql.py puts this in front of each
-- theme body, so every pillar ranks exactly the same facilities.
--   fac   one row per facility: id (_cng_fid of the source's own file, which is also the
--         boundary tiles' id), name, status class, lat, lon.
--   site  the res-8 cell holding the facility point (about 0.7 km²), for site variables.
--   ring  the res-8 cells whose centre lies within {{RADIUS}} miles of the facility.
-- FracTracker statuses are grouped into four classes and filtered by {{STATUS}}. Epoch is
-- filtered to US sites. PNNL projected sites are one growth scenario ({{GROWTH}}) at market
-- gravity weight 50, located by the centroid of their footprint.
fac0 AS (
  SELECT _cng_fid AS id, facility_name AS name, lat, long AS lon,
         CASE WHEN status IN ('Proposed', 'Pre-proposal') THEN 'proposed'
              WHEN status = 'Approved/Permitted/Under construction' THEN 'approved'
              WHEN status IN ('Operating', 'Expanding') THEN 'operating'
              ELSE 'halted' END AS status_class
  FROM read_parquet('s3://public-datacenters/fractracker/data-centers.parquet')
  WHERE '{{SOURCE}}' = 'fractracker' AND lat IS NOT NULL AND long IS NOT NULL
  UNION ALL
  SELECT _cng_fid, name, latitude, longitude, CASE WHEN operational THEN 'operating' ELSE 'approved' END
  FROM read_parquet('s3://public-datacenters/epoch/ai-data-centers.parquet')
  WHERE '{{SOURCE}}' = 'epoch' AND country = 'United States' AND latitude IS NOT NULL
  UNION ALL
  SELECT _cng_fid, COALESCE(NULLIF(name, ''), NULLIF(operator, ''), 'Campus ' || id), lat, lon, 'operating'
  FROM read_parquet('s3://public-datacenters/pnnl-im3/atlas-campus.parquet')
  WHERE '{{SOURCE}}' = 'pnnl-atlas'
  UNION ALL
  SELECT _cng_fid, 'Modelled site ' || id, ST_Y(ST_Centroid(geom)), ST_X(ST_Centroid(geom)), 'projected'
  FROM read_parquet('s3://public-datacenters/pnnl-im3/projected.parquet')
  WHERE '{{SOURCE}}' = 'pnnl-projected' AND growth_scenario = '{{GROWTH}}' AND market_gravity_weight = 50
  UNION ALL
  -- National baseline only (scripts/build-national.py; not a choice in the app): about 2,000
  -- res-8 cells of the contiguous US, picked by hash so the sample is the same on every run.
  SELECT DISTINCT h8::BIGINT, 'Sample cell', h3_cell_to_lat(h8), h3_cell_to_lng(h8), 'sample'
  FROM read_parquet('s3://public-census/census-2024/county/hex/h0=*/data_0.parquet')
  WHERE '{{SOURCE}}' = 'us-sample' AND hash(h8) % 5000 = 0 AND STATEFP NOT IN ('02', '15') AND STATEFP < '60'
),
fac AS MATERIALIZED (
  SELECT *, h3_latlng_to_cell(lat, lon, 8)::UBIGINT AS h8
  FROM fac0
  WHERE '{{SOURCE}}' <> 'fractracker' OR 'all' IN ({{STATUS}}) OR status_class IN ({{STATUS}})
),
site AS MATERIALIZED (
  SELECT id, h8, h3_cell_to_parent(h8, 0)::BIGINT AS h0, h3_cell_area(h8, 'km^2') AS a FROM fac
),
ring AS MATERIALIZED (
  SELECT id, h8, h3_cell_to_parent(h8, 0)::BIGINT AS h0, h3_cell_area(h8, 'km^2') AS a
  FROM (
    SELECT f.id, f.lat, f.lon,
           UNNEST(h3_grid_disk(f.h8, CAST(CEIL({{RADIUS}} * 1.609344 / 0.69) AS INTEGER) + 1))::UBIGINT AS h8
    FROM fac f
  )
  WHERE 2 * 6371.0088 * ASIN(SQRT(
          POWER(SIN(RADIANS(h3_cell_to_lat(h8) - lat) / 2), 2)
          + COS(RADIANS(lat)) * COS(RADIANS(h3_cell_to_lat(h8)))
            * POWER(SIN(RADIANS(h3_cell_to_lng(h8) - lon) / 2), 2)))
        <= {{RADIUS}} * 1.609344
),
-- Regulatory screen: how close each facility is to resources that trigger federal review
-- under NEPA and related laws, and how many of them lie in the site cell. Distances run from
-- the facility point to the centre of the nearest res-8 cell holding the resource, or 0 when
-- the site cell holds it; a facility with none within the radius gets the radius itself.
cells AS MATERIALIZED (SELECT DISTINCT h8, h0 FROM ring),
-- ESA section 7: USFWS final and proposed critical habitat
crit8 AS MATERIALIZED (
  SELECT DISTINCT k.h8
  FROM read_parquet('s3://public-usfws/critical-habitat/final/hex/h0=*/data_0.parquet') k
  SEMI JOIN cells c ON c.h8 = k.h8 AND c.h0 = k.h0
),
prop8 AS MATERIALIZED (
  SELECT DISTINCT k.h8
  FROM read_parquet('s3://public-usfws/critical-habitat/proposed/hex/h0=*/data_0.parquet') k
  SEMI JOIN cells c ON c.h8 = k.h8 AND c.h0 = k.h0
),
-- ESA section 7: USFWS ranges of listed and proposed species that cover the site cell, as
-- IPaC screens a project location. Ranges are coarse, often whole counties, so only the site
-- cell is used.
spsite AS MATERIALIZED (SELECT DISTINCT r.h8, r.h0 FROM ring r JOIN fac f USING (id) WHERE r.h8 = f.h8),
spp8 AS MATERIALIZED (
  SELECT s.h8, COUNT(DISTINCT s.ENTITY_ID) AS n
  FROM read_parquet('s3://public-usfws/species-ranges/hex/h0=*/data_0.parquet') s
  SEMI JOIN spsite c ON c.h8 = s.h8 AND c.h0 = s.h0
  WHERE s.STATUS_ABB IN ('Endangered', 'Threatened', 'Proposed Endangered', 'Proposed Threatened')
  GROUP BY s.h8
),
-- Clean Water Act section 404: NWI wetlands, the same classes as the water pillar
wet8 AS MATERIALIZED (
  SELECT DISTINCT n.h8
  FROM read_parquet('s3://public-wetlands/nwi-v2/hex/h0=*/data_0.parquet') n
  SEMI JOIN cells c ON c.h8 = n.h8 AND c.h0 = n.h0
  WHERE n.WETLAND_TYPE IN ('Freshwater Emergent Wetland', 'Freshwater Forested/Shrub Wetland', 'Estuarine and Marine Wetland')
),
-- Executive Order 11988: FEMA special flood hazard areas (1% annual chance A and V zones)
fld8 AS MATERIALIZED (
  SELECT DISTINCT z.h8
  FROM read_parquet('s3://public-hazard/flood-hazard/hex/h0=*/data_0.parquet') z
  SEMI JOIN cells c ON c.h8 = z.h8 AND c.h0 = z.h0
  WHERE z.SFHA_TF = 'T'
),
-- Wild and Scenic Rivers Act: designated rivers and Nationwide Rivers Inventory segments
riv8 AS MATERIALIZED (
  SELECT DISTINCT w.h8
  FROM read_parquet('s3://public-rivers/american-rivers/wild-scenic-designated/hex/h0=*/data_0.parquet') w
  SEMI JOIN cells c ON c.h8 = w.h8 AND c.h0 = w.h0
  UNION
  SELECT DISTINCT n.h8
  FROM read_parquet('s3://public-rivers/american-rivers/nri-2024/hex/h0=*/data_0.parquet') n
  SEMI JOIN cells c ON c.h8 = n.h8 AND c.h0 = n.h0
),
-- distance in miles from each facility to each ring cell, 0 for the site cell
dist AS MATERIALIZED (
  SELECT r.id, r.h8,
         CASE WHEN r.h8 = f.h8 THEN 0
              ELSE 2 * 3958.7613 * ASIN(SQRT(
                     POWER(SIN(RADIANS(h3_cell_to_lat(r.h8) - f.lat) / 2), 2)
                     + COS(RADIANS(f.lat)) * COS(RADIANS(h3_cell_to_lat(r.h8)))
                       * POWER(SIN(RADIANS(h3_cell_to_lng(r.h8) - f.lon) / 2), 2))) END AS mi
  FROM ring r JOIN fac f USING (id)
),
near AS (
  SELECT d.id,
         MIN(d.mi) FILTER (WHERE k.h8 IS NOT NULL) AS crit,
         MIN(d.mi) FILTER (WHERE p.h8 IS NOT NULL) AS prop,
         MIN(d.mi) FILTER (WHERE w.h8 IS NOT NULL) AS wet,
         MIN(d.mi) FILTER (WHERE z.h8 IS NOT NULL) AS fld,
         MIN(d.mi) FILTER (WHERE v.h8 IS NOT NULL) AS riv
  FROM dist d
  LEFT JOIN crit8 k USING (h8) LEFT JOIN prop8 p USING (h8) LEFT JOIN wet8 w USING (h8)
  LEFT JOIN fld8 z USING (h8) LEFT JOIN riv8 v USING (h8)
  GROUP BY d.id
),
agg AS (
  SELECT f.id,
         COALESCE(n.crit, {{RADIUS}}) AS crit, COALESCE(n.prop, {{RADIUS}}) AS prop,
         COALESCE(n.wet, {{RADIUS}}) AS wet, COALESCE(n.fld, {{RADIUS}}) AS fld,
         COALESCE(n.riv, {{RADIUS}}) AS riv, COALESCE(sp.n, 0) AS species,
         COALESCE(n.crit = 0, false)::INT + COALESCE(n.prop = 0, false)::INT + COALESCE(n.wet = 0, false)::INT
           + COALESCE(n.fld = 0, false)::INT + COALESCE(n.riv = 0, false)::INT AS on_site
  FROM fac f LEFT JOIN near n USING (id) LEFT JOIN spp8 sp ON sp.h8 = f.h8
),
vals AS (
  SELECT id, 'on_site' AS variable, 'Screened resources in the site cell' AS label, on_site AS value, 'resources' AS unit, 'int' AS fmt, 'linear' AS scale, 1 AS dir FROM agg
  UNION ALL SELECT id, 'listed_species', 'Listed and proposed species whose range covers the site', species, 'species', 'int', 'linear', 1 FROM agg
  UNION ALL SELECT id, 'critical_habitat_mi', 'Distance to final critical habitat', crit, 'miles', 'num1', 'linear', -1 FROM agg
  UNION ALL SELECT id, 'proposed_habitat_mi', 'Distance to proposed critical habitat', prop, 'miles', 'num1', 'linear', -1 FROM agg
  UNION ALL SELECT id, 'wetland_mi', 'Distance to a mapped wetland', wet, 'miles', 'num1', 'linear', -1 FROM agg
  UNION ALL SELECT id, 'floodplain_mi', 'Distance to a special flood hazard area', fld, 'miles', 'num1', 'linear', -1 FROM agg
  UNION ALL SELECT id, 'river_mi', 'Distance to a Wild and Scenic or inventoried river', riv, 'miles', 'num1', 'linear', -1 FROM agg
),
-- Score: mid-rank percentile, 0-100, among the facilities in view that have a value. Tied
-- values share the midpoint of their rank range. dir = +1 when a higher value means more
-- likely impact or concern, -1 when a lower value does.
ranked AS (
  SELECT *, CASE WHEN value IS NULL THEN NULL
                 ELSE ROUND(100 * ((RANK() OVER w - 1) + (COUNT(*) OVER w - 1)) / 2.0
                            / NULLIF(COUNT(*) OVER (PARTITION BY variable, value IS NULL) - 1, 0), 1)
            END AS pct
  FROM vals
  WINDOW w AS (PARTITION BY variable, value IS NULL ORDER BY dir * value)
)
-- value is kept to 4 significant figures
SELECT id, variable, label,
       CASE WHEN value IS NULL OR value = 0 THEN value
            ELSE ROUND(value, 3 - CAST(FLOOR(LOG10(ABS(value))) AS INTEGER)) END AS value,
       unit, fmt, scale, dir, pct,
       ROUND(AVG(pct) OVER (PARTITION BY id), 1) AS pillar_score
FROM ranked
ORDER BY id, variable
